def decorator_fab(deco, *dargs, **dkwargs):
    """Creates a decorator from a function with multiple parameters.

    Similar to calling decorator(deco), but explicitly creates a factory
    that can be called with decorator arguments.
    """
    return make_decorator(deco, dargs, dkwargs)

